example_item.example_item_data:
% Deux minutes de signal simule propre : presque chaque fenetre est utilisable.
recording = ecglab.simulate('Seconds', 120, 'Seed', 1);
q = ecglab.quality(recording);
fprintf('%.0f%% utilisable\n', 100 * q.usableFraction)

% Un debut propre et une fin bruitee : la plus longue bonne plage est le debut.
recording = ecglab.simulate('Seconds', 180, 'Seed', 2);
N = size(recording.samples, 1);
third = round(2 * N / 3);
recording.samples(third + 1:end, 1) = recording.samples(third + 1:end, 1) ...
  + 0.5 * randn(N - third, 1);
q = ecglab.quality(recording);
good = q.good
